  (202, 'dap_30a_cm', 'dap', 30, '25.37', 'cm', 25.37, 25.37, 'published_equation', 'média; extrapolação explícita', 'Hossfeld IV: DBH = 83.54(1 + 42.02 exp[-0.8551 ln(t)])^-1; t=30 anos.', 'https://coalizaobr.com.br/wp-content/uploads/2025/10/silviculture-and-wood-properties-of-native-species-of-the-atlantic-forest-of-brazil.pdf', 'equação extrapolada além da idade medida', 'Saída da equação Hossfeld IV publicada aos 30 anos; idade medida até cerca de 20–21 anos e fonte simula até 35. Extrapolação etária explícita, sem suavização.', 'Projeções e fontes', 'PC-TAX-0141'),
  (202, 'altura_30a_m', 'altura', 30, '12.261000000000001', 'm', 9.581000000000001, 15.7182, 'estimated', 'média: equação publicada; extrapolação etária', 'Hossfeld IV: DBH = 83.54(1 + 42.02 exp[-0.8551 ln(t)])^-1; t=30 anos.', 'https://coalizaobr.com.br/wp-content/uploads/2025/10/silviculture-and-wood-properties-of-native-species-of-the-atlantic-forest-of-brazil.pdf', 'idade desde plantio / estimativa operacional', 'Planting_age. Equação ajustada a medições do plantio até cerca de 20–21 anos; DAP30 = 25,37 cm é extrapolação da equação publicada (a obra simula crescimento até 35 anos), não medição aos 30. H30 permanece estimated.', 'Projeções e fontes', 'PC-TAX-0141'),
